lines.push('Гость: имя в WhatsApp — ' + (b.guest?.whatsappName || 'неизвестно') + '. Телефон подтверждён: ' + (b.guest?.verifiedPhone ? 'да (' + b.guest.verifiedPhone + ')' : 'нет') + '.');
const up = b.guest?.upcomingReservations || [];
