  guestName: b.guest?.whatsappName || '',
  guestWords: [...(b.history || []).filter(h => h.role === 'guest').map(h => h.text), g.text].join('
').slice(-6000),
  systemMessage: PROMPT.replace('{{ZONES}}', zones) + '

' + lines.join('
'),
